window.kbPageData["views/entry/k-a00a8fcb9d224472"] = {"key":"entry/k-a00a8fcb9d224472","state":{"route":"entry/k-a00a8fcb9d224472"},"node":{"id":"k-a00a8fcb9d224472","mode":"k","title":"收入分配制度","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2023 行政执法 行测#3","国考 2025 副省级 行测#10","国考 2025 地市级 行测#10","国考 2025 行政执法 行测#10"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":2,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["employment","modern"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["社会治理","经济"],"来源主题":["就业、社保与公共服务"],"资料类别":["非时政"]},"directorySummary":"收入分配制度规定收入如何形成、分配和调节。我国坚持按劳分配为主体、多种分配方式并存，构建初次分配、再分配、第三次分配协调配套的制度体系。","review":{"title":"收入分配制度","type":"制度与规则","definition":"收入分配制度规定收入如何形成、分配和调节。我国坚持按劳分配为主体、多种分配方式并存，构建初次分配、再分配、第三次分配协调配套的制度体系。","explanation":"初次分配形成劳动报酬等收入。政府通过税收、社会保障和转移支付等机制进行再分配。第三次分配主要通过社会力量自愿参与公益慈善等方式发挥作用。党的二十大报告将分配制度明确为促进共同富裕的基础性制度。","basis":"据关联原题及所列出处编释。","references":[{"source":"twenty","location":"完善分配制度"}],"related":["k-aa052a4589f73e60","k-abc7a40f1ee48790"],"domain":"经济","examFocus":{"国考 2023 行政执法 行测#3":"核对党的二十大报告中分配制度与民生目标的关系，并与就业、社会保障体系和人民健康的定位区分。","国考 2025 副省级 行测#10":"对照收入分配制度改革部署，按调节方式和作用区分初次分配、再分配和第三次分配。"}},"aspects":[{"title":"促进共同富裕的基础性作用","uses":[{"unit":"Q1","role":"直接考查","use":"本题 要求辨认党的二十大报告关于民生福祉的表述。D项准确对应完善分配制度部分。","evidence":"分配制度是促进共同富裕的基础性制度","qids":["国考 2023 行政执法 行测#3"]}]},{"title":"再分配调节机制","uses":[{"unit":"Q2","role":"直接考查","use":"本题 均为选非题。党的二十届三中全会2024年通过的《中共中央关于进一步全面深化改革 推进中国式现代化的决定》第42条将税收、社会保障、转移支付列为再分配调节机制。D项将其归为第三次分配，故三卷均选D。","evidence":"完善税收、社会保障、转移支付等第三次分配调节机制","qids":["国考 2025 副省级 行测#10","国考 2025 地市级 行测#10","国考 2025 行政执法 行测#10"]}]}],"sources":[{"id":"5cbd9b1179a2a2b6","label":"收入分配制度","topic":"就业、社保与公共服务","category":"非时政","text":"3.收入分配制度\n分配制度是促进共同富裕的基础性制度。党的二十届三中全会提出，“完善收入分配制\n度。构建初次分配、再分配、第三次分配协调配套的制度体系，提高居民收入在国民收入分\n配中的比重，提高劳动报酬在初次分配中的比重”。这为完善收入分配制度提供了基本遵循。\n要正确处理好初次分配、再分配、第三次分配的关系。\n初次分配是指在社会生产活动中，企业作为分配主体，将国民收入在国家、企业、个人\n之间进行分配，是最基本的分配关系，主要是在市场机制中形成的。再分配是指在初次分配\n结果的基础上，政府对收入分配进行再次调节的过程，目的在于调节城乡、区域、部门和劳\n动者之间的收入分配关系，保障社会公平。第三次分配是指企业、社会组织和个人在自愿基\n础上向他人进行捐赠或无偿提供帮助。初次分配是基础，再分配是保障，第三次分配是必要\n的补充。","source":{"doc":"6cbfb01fe723bba64b75","first":18,"last":19,"page":18,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"国考 2023 行政执法 行测#3":{"paper":"国考 2023 行政执法 行测","n":3,"mod":"常识判断","src":["857378cf496f27296500.pdf",1],"asrc":["d23139fe5a0fb3115135.pdf",2],"card":"55b6bac1ce4977682f18c37f","links":[{"id":"k-a00a8fcb9d224472","role":"直接考查","why":"题目直接考查分配制度对促进共同富裕的基础性作用。"}]},"国考 2025 副省级 行测#10":{"paper":"国考 2025 副省级 行测","n":10,"mod":"政治理论","src":["ffe12c35a46d4df574ec.pdf",2],"asrc":["ff0b352b44d417525086.pdf",4],"card":"01809ea03f41c1427239b240","links":[{"id":"k-a00a8fcb9d224472","role":"直接考查","why":"税收、社会保障和转移支付属于再分配调节机制，公益慈善事业属于第三次分配。"}]},"国考 2025 地市级 行测#10":{"paper":"国考 2025 地市级 行测","n":10,"mod":"政治理论","src":["31f401e91aef8d11365d.pdf",2],"asrc":["8cece062c7c079b53130.pdf",4],"card":"d9d2804e2ee057b246050ad1","links":[{"id":"k-a00a8fcb9d224472","role":"直接考查","why":"税收、社会保障和转移支付是再分配调节手段，公益慈善是第三次分配的重要形式。"}]},"国考 2025 行政执法 行测#10":{"paper":"国考 2025 行政执法 行测","n":10,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",2],"asrc":["e2c4b1970d2b49eac0fd.pdf",4],"card":"9d85b856d7778bd341fa3480","links":[{"id":"k-a00a8fcb9d224472","role":"直接考查","why":"税收、社会保障和转移支付属于再分配调节，公益慈善事业属于第三次分配。"}]}},"terms":{"k-aa052a4589f73e60":{"id":"k-aa052a4589f73e60","mode":"k","type":"概念与词义","title":"共同富裕","qs":[],"count":3},"k-abc7a40f1ee48790":{"id":"k-abc7a40f1ee48790","mode":"k","type":"观点与论证","title":"全体人民共同富裕的现代化","qs":[],"count":2}},"references":{"twenty":{"name":"党的二十大报告（2022年）","url":"https://www.miit.gov.cn/xwdt/szyw/art/2022/art_d664717b51f54b9886bc371c5f3594ed.html"}},"topics":[{"slug":"modern","title":"中国式现代化与民生"},{"slug":"employment","title":"就业质量与社会保障"}],"units":{"k-a00a8fcb9d224472":[["国考 2023 行政执法 行测#3"],["国考 2025 副省级 行测#10","国考 2025 地市级 行测#10","国考 2025 行政执法 行测#10"]]}};
